  clearMocks: true
};

export interface Frontmatter {
  title?: string;
  date?: string;
  tags?: string[];
  [key: string]: unknown;
}

export interface Page {
  slug: string;
  title: string;
  date: string | null;
  tags: string[];
  contentHtml: string;
  raw: string;
  frontmatter: Frontmatter;
  fileName: string;
}

export interface BuildOptions {
  contentDir: string;
  outputDir: string;
}

import matter from 'gray-matter';
import type { Frontmatter } from './types';

export interface ParsedMarkdown {
  content: string;
  data: Frontmatter;
}

export function parseFrontmatter(fileContents: string): ParsedMarkdown {
  const result = matter(fileContents);
  return {
    content: result.content,
    data: (result.data || {}) as Frontmatter
  };
}

export function extractTags(data: Frontmatter): string[] {
  const raw = data.tags;
  if (!Array.isArray(raw)) return [];
  return raw.filter((tag): tag is string => typeof tag === 'string');
}

import { marked } from 'marked';
import { parseFrontmatter, extractTags } from './frontmatter';
import type { Page } from './types';
import { basename } from 'path';

marked.setOptions({ gfm: true, breaks: false });

export function markdownToHtml(markdown: string): string {
  return marked.parse(markdown) as string;
}

export function slugify(input: string): string {
  return input
    .replace(/\.md$/i, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '') || 'untitled';
}

export function pageFileName(fileName: string): string {
  const base = basename(fileName);
  const slug = slugify(base);
  return `${slug}.html`;
}

export function parsePage(fileName: string, fileContents: string): Page {
  const { content, data } = parseFrontmatter(fileContents);
  const tags = extractTags(data);
  const date = typeof data.date === 'string' ? data.date : null;
  return {
    slug: slugify(basename(fileName)),
    title: typeof data.title === 'string' ? data.title : slugify(basename(fileName)),
    date,
    tags,
    contentHtml: markdownToHtml(content),
    raw: fileContents,
    frontmatter: data,
    fileName
  };
}

import { promises as fs } from 'fs';
import { join, relative, basename } from 'path';
import { parsePage, pageFileName } from './markdown';
import type { Page, BuildOptions } from './types';

function escapeHtml(input: string): string {
  return input
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&#39;');
}

function renderTags(tags: string[]): string {
  if (tags.length === 0) return '';
  const chips = tags.map((tag) => `<span class="tag">${escapeHtml(tag)}</span>`).join('');
  return `<div class="tags">${chips}</div>`;
}

function renderPageBody(page: Page): string {
  const dateLine = page.date ? `<time datetime="${escapeHtml(page.date)}">${escapeHtml(page.date)}</time>` : '';
  return `
<article class="page">
  <h1 class="page-title">${escapeHtml(page.title)}</h1>
  ${dateLine}
  ${renderTags(page.tags)}
  <div class="page-content">${page.contentHtml}</div>
  <p><a href="index.html">&larr; Back to index</a></p>
</article>`;
}

function layoutShell(body: string, title: string): string {
  return `<!DOCTYPE html>
<html lang="en">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${escapeHtml(title)}</title>
</head>
<body>
${body}
</body>
</html>
`;
}

export function renderPage(page: Page): string {
  return layoutShell(renderPageBody(page), page.title);
}

export function renderIndex(pages: Page[]): string {
  const sorted = [...pages].sort((a, b) => {
    if (a.date && b.date) return b.date.localeCompare(a.date);
    return a.title.localeCompare(b.title);
  });

  const items = sorted
    .map((page) => {
      const href = pageFileName(page.fileName);
      return `<li>
  <a href="${escapeHtml(href)}">${escapeHtml(page.title)}</a>
  ${page.date ? `<time datetime="${escapeHtml(page.date)}">${escapeHtml(page.date)}</time>` : ''}
  ${renderTags(page.tags)}
</li>`;
    })
    .join('\n');

  const payload = escapeHtml(JSON.stringify(sorted.map((p) => ({
    title: p.title,
    date: p.date,
    tags: p.tags,
    href: pageFileName(p.fileName)
  }))));

  const body = `
<header class="site-header">
  <h1>Pages</h1>
</header>
<ul class="page-list" id="page-list">${items}</ul>
<div id="app" hidden></div>
<script id="ssg-data" type="application/json">${payload}</script>
<script>
  (function () {
    var data = JSON.parse(document.getElementById('ssg-data').textContent);
    var list = document.getElementById('page-list');
    if (data.length === 0) {
      list.innerHTML = '<li>No pages found.</li>';
    }
    var app = document.getElementById('app');
    var links = list.querySelectorAll('a');
    for (var i = 0; i < links.length; i++) {
      (function (link) {
        link.addEventListener('click', function (e) {
          e.preventDefault();
          var target = link.getAttribute('href');
          var page = null;
          for (var j = 0; j < data.length; j++) {
            if (data[j].href === target) { page = data[j]; break; }
          }
          if (page) {
            app.innerHTML = '<h1>' + page.title + '</h1>' +
              (page.date ? '<time>' + page.date + '</time>' : '') +
              '<p><a href="index.html">&larr; Back to index</a></p>';
            app.hidden = false;
            list.hidden = true;
          }
        });
      })(links[i]);
    }
  })();
</script>
`;
  return layoutShell(body, 'Pages');
}

export async function collectPages(contentDir: string): Promise<Page[]> {
  const entries = await fs.readdir(contentDir, { withFileTypes: true });
  const pages: Page[] = [];
  for (const entry of entries) {
    if (!entry.isFile() || !/\.md$/i.test(entry.name)) continue;
    const fullPath = join(contentDir, entry.name);
    const contents = await fs.readFile(fullPath, 'utf8');
    pages.push(parsePage(entry.name, contents));
  }
  return pages;
}

export async function buildSite(options: BuildOptions): Promise<Page[]> {
  const contentDir = options.contentDir;
  const outputDir = options.outputDir;

  await fs.mkdir(outputDir, { recursive: true });

  const pages = await collectPages(contentDir);

  const indexHtml = renderIndex(pages);
  await fs.writeFile(join(outputDir, 'index.html'), indexHtml, 'utf8');

  for (const page of pages) {
    const html = renderPage(page);
    await fs.writeFile(join(outputDir, pageFileName(page.fileName)), html, 'utf8');
  }

  return pages;
}

import { resolve } from 'path';
import { buildSite } from './generator';
import type { BuildOptions } from './types';

export const DEFAULT_CONTENT_DIR = 'content';
export const DEFAULT_OUTPUT_DIR = 'dist';

export interface ParsedArgs {
  command: string;
  options: BuildOptions;
}

export function parseArgs(argv: string[]): ParsedArgs {
  const options: BuildOptions = {
    contentDir: resolve(process.cwd(), DEFAULT_CONTENT_DIR),
    outputDir: resolve(process.cwd(), DEFAULT_OUTPUT_DIR)
  };

  let command = 'build';
  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === '--content' || arg === '-c') {
      options.contentDir = resolve(process.cwd(), argv[++i]);
    } else if (arg === '--output' || arg === '-o') {
      options.outputDir = resolve(process.cwd(), argv[++i]);
    } else if (arg.startsWith('--content=')) {
      options.contentDir = resolve(process.cwd(), arg.slice('--content='.length));
    } else if (arg.startsWith('--output=')) {
      options.outputDir = resolve(process.cwd(), arg.slice('--output='.length));
    } else if (!arg.startsWith('-')) {
      command = arg;
    } else if (arg === '--help' || arg === '-h') {
      command = 'help';
    }
  }
  return { command, options };
}

export function printHelp(): string {
  return [
    'ssg - a static site generator',
    '',
    'Usage:',
    '  npx ssg build [options]',
    '',
    'Options:',
    '  --content <dir>    Markdown content directory (default: ./content)',
    '  --output <dir>     Output directory (default: ./dist)',
    '  -h, --help         Show this help message'
  ].join('\n');
}

export async function run(argv: string[]): Promise<void> {
  const { command, options } = parseArgs(argv);

  if (command === 'help') {
    process.stdout.write(printHelp() + '\n');
    return;
  }

  if (command !== 'build') {
    throw new Error(`Unknown command: ${command}`);
  }

  const pages = await buildSite(options);
  process.stdout.write(`Built ${pages.length} page(s) from ${options.contentDir} into ${options.outputDir}\n`);
}

if (require.main === module) {
  run(process.argv.slice(2)).catch((error: Error) => {
    process.stderr.write(`Error: ${error.message}\n`);
    process.exit(1);
  });
}

import { parseFrontmatter, extractTags } from '../src/frontmatter';

