describe('parsePage', () => {
  it('builds a page with frontmatter and html content', () => {
    const page = parsePage(
      'hello.md',
      '---\ntitle: Hello\n---\n\n# Welcome'
    );
    expect(page.slug).toBe('hello');
    expect(page.title).toBe('Hello');
    expect(page.tags).toEqual([]);
