  });

  it('uses the slug as title when title is missing', () => {
    const page = parsePage('no-title.md', '# Just body');
    expect(page.title).toBe('no-title');
  });

  it('captures tags and date', () => {
    const page = parsePage(
      'post.md',
      '---\ntitle: Post\ndate: 2024-02-02\ntags: [news, tech]\n---\nbody'
    );
    expect(page.date).toBe('2024-02-02');
    expect(page.tags).toEqual(['news', 'tech']);
  });
});

import { promises as fs } from 'fs';
import { join } from 'path';
import { tmpdir } from 'os';
import {
  collectPages,
  buildSite,
  renderIndex,
  renderPage
} from '../src/generator';

async function makeContent(dir: string, files: Record<string, string>): Promise<void> {
  await fs.mkdir(dir, { recursive: true });
  for (const [name, contents] of Object.entries(files)) {
    await fs.writeFile(join(dir, name), contents, 'utf8');
  }
}

describe('collectPages', () => {
  it('reads all markdown files and skips non-md files', async () => {
    const dir = join(tmpdir(), `ssg-collect-${Date.now()}`);
    await makeContent(dir, {
      'a.md': '---\ntitle: A\n---\n# A',
      'b.md': '---\ntitle: B\n---\n# B',
      'notes.txt': 'not markdown'
    });

    const pages = await collectPages(dir);
    expect(pages).toHaveLength(2);
    expect(pages.map((p) => p.slug).sort()).toEqual(['a', 'b']);
    await fs.rm(dir, { recursive: true, force: true });
  });

  it('returns an empty list for an empty directory', async () => {
    const dir = join(tmpdir(), `ssg-empty-${Date.now()}`);
    await fs.mkdir(dir, { recursive: true });
    const pages = await collectPages(dir);
    expect(pages).toEqual([]);
    await fs.rm(dir, { recursive: true, force: true });
  });
});

describe('buildSite', () => {
  let contentDir: string;
  let outputDir: string;

  beforeEach(async () => {
    contentDir = join(tmpdir(), `ssg-content-${Date.now()}`);
    outputDir = join(tmpdir(), `ssg-dist-${Date.now()}`);
    await makeContent(contentDir, {
      'hello-world.md': [
        '---',
        'title: Hello World',
        'date: 2024-01-01',
        'tags: [intro, demo]',
        '---',
        '',
        '## Welcome',
        '',
        'This is **bold**.'
      ].join('\n'),
      'about.md': '---\ntitle: About\n---\n\n# About us'
    });
  });

  afterEach(async () => {
    await fs.rm(contentDir, { recursive: true, force: true });
    await fs.rm(outputDir, { recursive: true, force: true });
  });

  it('generates index.html and one HTML file per page', async () => {
    const pages = await buildSite({ contentDir, outputDir });

    expect(pages).toHaveLength(2);

    const index = await fs.readFile(join(outputDir, 'index.html'), 'utf8');
    expect(index).toContain('Hello World');
    expect(index).toContain('About');

    const hello = await fs.readFile(join(outputDir, 'hello-world.html'), 'utf8');
    expect(hello).toContain('Hello World');
    expect(hello).toContain('<strong>bold</strong>');
    expect(hello).toContain('<h2>Welcome</h2>');

    const about = await fs.readFile(join(outputDir, 'about.html'), 'utf8');
    expect(about).toContain('About us');

    const files = await fs.readdir(outputDir);
    expect(files).toEqual(expect.arrayContaining(['index.html', 'hello-world.html', 'about.html']));
  });

  it('creates the output directory when it does not exist', async () => {
    await fs.rm(outputDir, { recursive: true, force: true });
    await buildSite({ contentDir, outputDir });
    const stat = await fs.stat(outputDir);
    expect(stat.isDirectory()).toBe(true);
  });

  it('renders tags on the index page', async () => {
    await buildSite({ contentDir, outputDir });
    const index = await fs.readFile(join(outputDir, 'index.html'), 'utf8');
    expect(index).toContain('intro');
    expect(index).toContain('demo');
  });
});

describe('renderIndex', () => {
  it('includes an SPA runtime payload', () => {
    const html = renderIndex([]);
    expect(html).toContain('id="ssg-data"');
    expect(html).toContain('application/json');
  });
});

describe('renderPage', () => {
  it('renders a standalone HTML document', () => {
    const html = renderPage({
      slug: 'x',
      title: 'X',
      date: null,
      tags: ['t'],
      contentHtml: '<p>hi</p>',
      raw: '',
      frontmatter: {},
      fileName: 'x.md'
    });
    expect(html).toContain('<!DOCTYPE html>');
    expect(html).toContain('<title>X</title>');
    expect(html).toContain('<p>hi</p>');
  });
});

import { promises as fs } from 'fs';
import { join } from 'path';
import { tmpdir } from 'os';
import { parseArgs, run, printHelp, DEFAULT_CONTENT_DIR, DEFAULT_OUTPUT_DIR } from '../src/cli';
import { buildSite } from '../src/generator';

jest.mock('../src/generator', () => ({
  buildSite: jest.fn()
}));

const mockedBuildSite = buildSite as jest.Mock;

describe('parseArgs', () => {
  it('defaults content to ./content and output to ./dist', () => {
    const { command, options } = parseArgs(['build']);
    expect(command).toBe('build');
    expect(options.contentDir.endsWith(`/${DEFAULT_CONTENT_DIR}`)).toBe(true);
    expect(options.outputDir.endsWith(`/${DEFAULT_OUTPUT_DIR}`)).toBe(true);
  });

  it('parses --content and --output flags', () => {
    const { options } = parseArgs(['build', '--content', 'src/md', '--output', 'public']);
    expect(options.contentDir.endsWith('/src/md')).toBe(true);
    expect(options.outputDir.endsWith('/public')).toBe(true);
  });

  it('parses equals-style options', () => {
    const { options } = parseArgs(['build', '--content=src/md', '--output=public']);
    expect(options.contentDir.endsWith('/src/md')).toBe(true);
    expect(options.outputDir.endsWith('/public')).toBe(true);
  });

  it('sets command to help for --help', () => {
    const { command } = parseArgs(['--help']);
    expect(command).toBe('help');
  });
});

describe('printHelp', () => {
  it('mentions build, content and output', () => {
    const help = printHelp();
    expect(help).toContain('ssg build');
    expect(help).toContain('--content');
    expect(help).toContain('--output');
  });
});

describe('run', () => {
  it('runs the build with parsed options', async () => {
    mockedBuildSite.mockResolvedValue([{ slug: 'a' }]);
    const out = join(tmpdir(), `ssg-out-${Date.now()}`);

    const log = jest.spyOn(process.stdout, 'write').mockImplementation(() => true);

    await run(['build', '--content', 'x', '--output', out]);

    expect(mockedBuildSite).toHaveBeenCalledTimes(1);
    expect(mockedBuildSite.mock.calls[0][0].outputDir.endsWith(out)).toBe(true);
    expect(log).toHaveBeenCalledWith(expect.stringContaining('Built 1 page(s)'));
    log.mockRestore();
  });

  it('prints help for the help command without building', async () => {
    const log = jest.spyOn(process.stdout, 'write').mockImplementation(() => true);
    await run(['--help']);
    expect(mockedBuildSite).not.toHaveBeenCalled();
    expect(log).toHaveBeenCalledWith(expect.stringContaining('ssg build'));
    log.mockRestore();
  });

  it('rejects unknown commands', async () => {
    await expect(run(['serve'])).rejects.toThrow('Unknown command');
  });
});

